        return { recorded: true };
      },
    }),
    complete_session: tool({
      description: 'Finish the session with a summary of the journal entry.',
      inputSchema: completeSessionInput,
      execute: async (input) => {
        summary = input.summary;
        return { completed: true };
      },
    }),
  };

